"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["8742"],{82170(e){e.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.processo_seletivo.precedencia_fase_violada","status":422,"titulo":"A ordem declarada viola a preced\xeancia entre fases do cadastro"},"descricao":{"codigo":"uniplus.selecao.processo_seletivo.precedencia_fase_violada","requisitos":[],"oQueAconteceu":["O cadastro de fases estabelece que certas fases precedem outras. Quando as duas\\nfases de uma dessas rela\xe7\xf5es est\xe3o no cronograma, a que precede precisa ter ordem\\nmenor que a que sucede. O cronograma enviado coloca a antecessora com ordem igual\\nou maior que a da sucessora.","A recusa s\xf3 considera rela\xe7\xf5es em que as duas fases est\xe3o no cronograma; o\\ncronograma que cont\xe9m s\xf3 uma delas n\xe3o viola nada. A mensagem da resposta cita\\nas duas fases e as ordens declaradas. Nada \xe9 gravado, e o cronograma anterior\\ncontinua como estava.","O campo da recusa \xe9 a `ordem` da fase sucessora, em que a posi\xe7\xe3o `i` \xe9 a dela:\\nao definir o cronograma (`PUT`), `fases[i].ordem`, sem identificadores; na\\npublica\xe7\xe3o e na retifica\xe7\xe3o em ato \xfanico, `/cronograma/fases/{i}/ordem`, com o\\nc\xf3digo da fase sucessora em `identificadores`, no formato\\n`[{\\"lista\\": \\"fases\\", \\"identificador\\": \\"<c\xf3digo da fase sucessora>\\"}]`.","Se a ordem est\xe1 invertida e o edital marcou uma das fases com \\"no mesmo momento\\nda anterior\\", de modo que a marca junta as duas, a recusa \xe9 a de\\n[fases ligadas por preced\xeancia no mesmo momento](/erros/uniplus.selecao.processo_seletivo.fases_com_precedencia_no_mesmo_momento)."],"comoResolver":["Reordene o cronograma para que a fase antecessora venha antes da sucessora e\\nenvie de novo. Se voc\xea acredita que a rela\xe7\xe3o de preced\xeancia do cadastro est\xe1\\nerrada, ela \xe9 mantida pela unidade respons\xe1vel pelo cat\xe1logo de fases, e n\xe3o\\npode ser contornada no cronograma do processo."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo","Publica\xe7\xe3o inicial do processo seletivo","Retifica\xe7\xe3o em ato \xfanico"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Processo seletivo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"3eb7bd1a0a2ae187ab8630a6fec1e327066b7a40"}}')}}]);